typedef float time_value_t;
typedef float rational_t;

struct vector3d
{
    float x, y, z;
};

extern "C" float powf(float, float);
extern "C" void fast_sin_cos_approx(float, float *, float *)
    __asm__("fast_sin_cos_approx__FfPfT1");

inline float fast_cos(float rads)
{
    float sinx, cosx;
    fast_sin_cos_approx(rads, &sinx, &cosx);
    return cosx;
}

inline float fast_sin(float rads)
{
    float sinx, cosx;
    fast_sin_cos_approx(rads, &sinx, &cosx);
    return sinx;
}

class vector_filter
{
public:
    void Filter_Vector(vector3d &, time_value_t, float, float);

private:
    rational_t xwPos[2];
    rational_t ywPos[2];
    rational_t zwPos[2];
    rational_t xerr[2];
    rational_t yerr[2];
    rational_t zerr[2];
};

void vector_filter::Filter_Vector(vector3d &filtered_vec, time_value_t time_step, float filter_speed_r, float filter_speed_i)
{
    if (time_step > 0.1f)
        time_step = 0.1f;
    else if (time_step < 0.014f)
        time_step = 0.014f;

    if (filter_speed_i == 1000000)
        filter_speed_i = filter_speed_r;

    float r = filter_speed_r * 6.9282f;
    float i = filter_speed_i * 4.0f;

    float eneg = 0.36787944f;
    float coeff = powf(eneg, r * time_step);
    float coss = fast_cos(i * time_step);
    float sins = fast_sin(i * time_step);
    float r1 = -coeff * coss;
    float i1 = coeff * sins;

    float a = r1 * r1 + i1 * i1;
    float g = 2.0f * r1 + a + 1.0f;

    float error = filtered_vec.x - xwPos[0];
    filtered_vec.x = (a + 1.0f) * xwPos[0] - a * xwPos[1] + g * xerr[0];

    xwPos[1] = xwPos[0];
    xwPos[0] = filtered_vec.x;
    xerr[1] = xerr[0];
    xerr[0] = error;

    error = filtered_vec.y - ywPos[0];
    filtered_vec.y = (a + 1.0f) * ywPos[0] - a * ywPos[1] + g * yerr[0];

    ywPos[1] = ywPos[0];
    ywPos[0] = filtered_vec.y;
    yerr[1] = yerr[0];
    yerr[0] = error;

    error = filtered_vec.z - zwPos[0];
    filtered_vec.z = (a + 1.0f) * zwPos[0] - a * zwPos[1] + g * zerr[0];

    zwPos[1] = zwPos[0];
    zwPos[0] = filtered_vec.z;
    zerr[1] = zerr[0];
    zerr[0] = error;
}
